/**
 * Subject line convention — "<Project Name> <SWPPP-acronym>", matching the
 * actual emails Derek's team sends from Pipedrive (verified against the sent
 * mailbox, e.g. "Stadium Dr Imp SWPPP", "Tanner Williams Comm Pk Expansion
 * CBMPP"). The SWPPP acronym is the lead's resolved `{SWPPP}` merge value
 * (default "SWPPP"; some scopes/states use CBMPP etc.). Apollo sequence steps
 * can override per-step; this is just the default the draft starts with.
 */
export function defaultSubject(leadTitle, swpppAcronym) {
  const title = (leadTitle || "").trim();
  const acr = (swpppAcronym || "SWPPP").trim();
  return title ? `${title} ${acr}` : acr;
}

/**
 * Render a template body with the standard merge fields.
 * Signature auto-appends "\nwww.ProSWPPP.com" to match legacy behavior.
 */
export function renderTemplate(body, { first, env, swppp, sig } = {}) {
  return String(body)
    .replace(/\{First\}/g, first || "there")
    .replace(/\{ENV\}/g, env || "EPA")
    .replace(/\{SWPPP\}/g, swppp || "SWPPP")
    .replace(/\{Sig\}/g, (sig || "") + "\nwww.ProSWPPP.com");
}

/**
 * Produce the day-0 (first-touch) draft body for a trigger type.
 */
export function renderFirstTouch(triggerType, ctx) {
  const t = (triggerType || "").toUpperCase();
  const steps = SDR_TEMPLATES[t];
  if (!steps?.length) throw new Error(`Unknown trigger type: ${triggerType}`);
  return renderTemplate(steps[0].body, ctx);
}

/**
 * Return ALL steps rendered (mainly for previewing what an Apollo sequence
 * should be configured to send). Day-0 = first email, day-3/6 = follow-ups.
 */
export function renderAllSteps(triggerType, ctx) {
  const t = (triggerType || "").toUpperCase();
  const steps = SDR_TEMPLATES[t];
  if (!steps?.length) throw new Error(`Unknown trigger type: ${triggerType}`);
  return steps.map((s) => ({ day: s.day, body: renderTemplate(s.body, ctx) }));
}
